import React, { useEffect, useState } from 'react';
import {BoardWrapper, BoardList, BoardItem} from '../../components/board';

interface boardItemType{
    title:string;
    author:string;
    create_at:string;
    note:string;
    name:string;
}

interface boardItemsType extends Array<boardItemType>{}

const BoardListLayer:React.FC = () => {
    // const items = testData;
    const [items, setItems] = useState<boardItemsType>([]);

    useEffect(()=>{
        if(items.length === 0){
            fetch("/static/boardList.json",
            {
                method: "GET",
                headers: {
                    "Content-type": "application/json"
                },
            })
            .then((response) => response.json())
            .then(data => {
                setItems(data);
            })
        }
    }, [items]);

    return(
        <BoardWrapper>
            <BoardList>
                {items 
                ?   items.map( (item ) => (
                        <BoardItem 
                            key={`border-item-${item.title}`}
                            title={item.title} 
                            author={item.author} 
                            create_at={item.create_at} 
                            note={item.note} 
                            name={item.name}
                        ></BoardItem>
                    )
                )
                : "게시글이 없습니다."}
            </BoardList>
        </BoardWrapper>
    )
}
export default BoardListLayer;