import React from 'react';
import styled from '@emotion/styled';
import marked from 'marked';

interface boardViewType{
    text: string;
}

const BoardView:React.FC<boardViewType> = ({text}) => {

    const getMarkdownText = () => {
        const rawMarkup = marked(text, {sanitize: true});
        return { __html: rawMarkup}
    }

    const View = styled.div`
        max-width: 96%;

        padding: 2%;
        
        /* Head Style */
        /* Title */
        h1 {
            font-size: 2.5em;
            color: black;
            text-align: center;

            & > a {
                :link{
                    color: black;
                    text-decoration: none;
                }
                :visited{
                    color: black;
                }
                :hover{
                    color: whitesmoke;
                    transition-duration: 0.5s;
                }
            }
        }
        /* Sub Title */
        h2 {
            font-size: 2em;
            border-bottom: 1px solid black;
        }
        h3 {
            font-size: 1.8em;
            padding-left: 0.5em;
            margin-block-end: 0.5em;
        }
        h4 {
            font-size: 1.5em;
            padding-left: 1em;
            margin-block-end: 0.5em;
        }
        h4 + ul {
            padding-inline-start: 50px;
        }
        h5 {
            font-size: 1.2em;
            padding-left: 1.5em;
            margin-block-end: 0.5em;
        }
        h5 + ul {
            padding-inline-start: 60px;
        }
        h6 {
            font-size: 1em;
            padding-left: 2em;
            margin-block-end: 0.5em;
        }
        h6 + ul {
            padding-inline-start: 70px;
        }

        /* 임시 li style */
        li {
            margin: 10px 0;
        } 

        /* Test Style */
        p {
            text-align: center;
        }
        h2 + p, li > p  {
            text-align: start;
        }

        /* Image */
        img{
            max-width: 90%;
            
        }

        /* Table */
        table{
            border: 1px solid black;

            border-collapse: collapse;

            td, tr {
                border-left: 1px solid black;
                border-right: 1px solid black;
            }

            & > thead{
                border-bottom: 1px solid black;
            }

            & > tbody{
                tr:nth-of-type(2n + 1){
                    background-color: darkgray;
                }
            }
        }

        /* 문자열 */
        code{
            background-color: black;
            border-radius: 3px;
            color: orange;
            padding: 1px 3px;
        }
    `;


    return(
        <View dangerouslySetInnerHTML={getMarkdownText()}>
        </View>
    );
}

export default BoardView;